//! Text: the pixel font ([`crate::fonts`], generated by tools/font.py) drawn through
//! [`Canvas::blit`]. Each glyph is one window of `advance` x `height` pixels, blended onto a known background
//! colour, so a string overwrites what was under it without a clear first.

use crate::ui::Canvas;

/// One character: its cell is `advance` x the font height; the ink is the `w` x `h` box at (`x`, `y`) in the
/// cell, 4 bits of coverage per pixel (high nibble first), row by row from byte `at` of [`Font::alpha`].
pub struct Glyph {
    /// Cell width: where the next character starts.
    pub advance: u8,
    /// Ink box left edge, in the cell.
    pub x: u8,
    /// Ink box top edge, in the cell.
    pub y: u8,
    /// Ink box width.
    pub w: u8,
    /// Ink box height.
    pub h: u8,
    /// First byte of the ink in [`Font::alpha`].
    pub at: u32,
}

/// A font: printable ASCII (0x20..=0x7e), then glyphs for control codes from 1 on (the pixel font's arrows); other
/// characters are drawn as `?`.
pub struct Font {
    /// Line height in pixels (the height of every cell).
    pub height: u8,
    /// Glyphs for 0x20..=0x7e.
    pub glyphs: &'static [Glyph],
    /// Coverage of all glyphs, 4 bits per pixel.
    pub alpha: &'static [u8],
}

impl Font {
    fn glyph(&self, c: char) -> &Glyph {
        // control codes 1 to 31 after the printable ones (the pixel font's cue arrows, tools/pixel_font.py)
        let i = match c as usize {
            k @ 1..0x20 => 0x5e + k,
            k => k.wrapping_sub(0x20),
        };
        match self.glyphs.get(i) {
            Some(g) => g,
            None => &self.glyphs[usize::from(b'?' - 0x20)],
        }
    }

    /// Coverage 0..=15 of pixel (`px`, `py`) of glyph `g`'s cell.
    fn coverage(&self, g: &Glyph, px: u32, py: u32) -> u8 {
        let (x, y) = (px.wrapping_sub(u32::from(g.x)), py.wrapping_sub(u32::from(g.y)));
        if x >= u32::from(g.w) || y >= u32::from(g.h) {
            return 0;
        }
        let n = y * u32::from(g.w) + x;
        let byte = self.alpha.get((g.at + n / 2) as usize).copied().unwrap_or(0);
        if n % 2 == 0 { byte >> 4 } else { byte & 0xf }
    }

    /// Width of `s` in pixels.
    pub fn width(&self, s: &str) -> u32 {
        s.chars().map(|c| u32::from(self.glyph(c).advance)).sum()
    }
}

/// `fg` over `bg` at coverage `a` (0..=15), channel by channel in RGB565.
///
/// ```
/// use bryton_rustfw::text::blend;
/// assert_eq!(blend(0xffff, 0x0000, 15), 0xffff);
/// assert_eq!(blend(0xffff, 0x0000, 0), 0x0000);
/// assert_eq!(blend(0xf800, 0x0000, 8) >> 11, 17); // red 31 at 8/15: 17
/// ```
pub fn blend(fg: u16, bg: u16, a: u8) -> u16 {
    let a = u32::from(a.min(15));
    let mix = |shift: u32, mask: u32| {
        let (f, b) = ((u32::from(fg) >> shift) & mask, (u32::from(bg) >> shift) & mask);
        ((f * a + b * (15 - a) + 7) / 15) << shift
    };
    (mix(11, 0x1f) | mix(5, 0x3f) | mix(0, 0x1f)) as u16
}

/// The face of the text (the FONT setting): the project's own dot matrix, or one of the two smooth fonts drawn into its
/// cells ([`crate::fonts::smooth`]). The order is FONT's cycle and the settings file's index (0 PIXEL, 1 BARLOW;
/// an older file's 1 was SMOOTH).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum Face {
    /// The project's dot matrix ([`crate::fonts::PIXEL`]).
    #[default]
    Pixel,
    /// Barlow Semi Condensed Bold.
    Barlow,
}

impl Face {
    /// Every face, in FONT's order.
    pub const ALL: [Face; 2] = [Face::Pixel, Face::Barlow];

    /// The name FONT shows.
    pub fn name(self) -> &'static str {
        match self {
            Face::Pixel => "PIXEL",
            Face::Barlow => "BARLOW",
        }
    }

    /// The next face in FONT's order (BARLOW is followed by PIXEL).
    pub fn next(self) -> Face {
        match self {
            Face::Pixel => Face::Barlow,
            Face::Barlow => Face::Pixel,
        }
    }
}

/// How text looks: a font, its scale and its colours. The UI defines its styles once (src/ui/mod.rs) and draws with them.
pub struct Style {
    /// The font.
    pub font: &'static Font,
    /// Each font pixel drawn as `scale` x `scale` (the pixel font is drawn at 2 or more).
    pub scale: u32,
    /// Ink colour, RGB565.
    pub fg: u16,
    /// Background the ink is blended onto: what is under the text.
    pub bg: u16,
}

impl Style {
    /// Width of `s` in screen pixels.
    pub fn width(&self, s: &str) -> u32 {
        self.font.width(s) * self.scale
    }

    /// Line height in screen pixels.
    pub fn height(&self) -> u32 {
        u32::from(self.font.height) * self.scale
    }
}

/// The font, glyph and scale `ch` is drawn with in `style`: with `smooth` (the FONT setting) and a smooth font for
/// the style's scale that has the glyph ([`crate::fonts::smooth`]), that glyph 1:1, else the style's own glyph at its
/// scale. Both have the same cell, so layouts do not depend on the choice.
fn pick(style: &Style, face: Face, ch: char) -> (&'static Font, &'static Glyph, u32) {
    let scale = style.scale.max(1);
    if face != Face::Pixel
        && let Some(f) = crate::fonts::smooth(face, scale)
    {
        let g = f.glyph(ch);
        if g.advance != 0 {
            return (f, g, 1);
        }
    }
    (style.font, style.font.glyph(ch), scale)
}

/// Where a string goes, relative to the `x` given to [`draw`].
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Align {
    /// `x` is the left edge.
    Left,
    /// `x` is the centre.
    Centre,
    /// `x` is the right edge.
    Right,
}

/// Draws `s` in `style` with its cells' top at `y`, and returns its width. Callers keep it on screen.
pub fn draw(c: &mut impl Canvas, style: &Style, x: u32, y: u32, align: Align, s: &str) -> u32 {
    let (fg, bg) = (c.ink(style.fg), c.ink(style.bg));
    let face = c.face();
    let width = style.width(s);
    let mut x = match align {
        Align::Left => x,
        Align::Centre => x.saturating_sub(width / 2),
        Align::Right => x.saturating_sub(width),
    };
    let mut palette = [bg; 16];
    for (a, p) in palette.iter_mut().enumerate() {
        *p = blend(fg, bg, a as u8);
    }
    for ch in s.chars() {
        let (font, g, k) = pick(style, face, ch);
        let w = u32::from(g.advance) * k;
        c.blit(x, y, w, style.height(), &mut |px, py| palette[usize::from(font.coverage(g, px / k, py / k))]);
        x += w;
    }
    width
}

/// Draws `s` from `x` as [`draw`] does, but nothing at or right of `right`: the last glyph's cell is cut there (its
/// blank columns, when the text was laid out by its ink). Returns where the text drawn ends.
pub fn draw_clipped(c: &mut impl Canvas, style: &Style, x: u32, y: u32, right: u32, s: &str) -> u32 {
    let (fg, bg) = (c.ink(style.fg), c.ink(style.bg));
    let face = c.face();
    let mut palette = [bg; 16];
    for (a, p) in palette.iter_mut().enumerate() {
        *p = blend(fg, bg, a as u8);
    }
    let mut x = x;
    for ch in s.chars() {
        let (font, g, k) = pick(style, face, ch);
        let w = (u32::from(g.advance) * k).min(right.saturating_sub(x));
        if w == 0 {
            break;
        }
        c.blit(x, y, w, style.height(), &mut |px, py| palette[usize::from(font.coverage(g, px / k, py / k))]);
        x += w;
    }
    x
}

/// Character `old` drawn at (`x`, `y`) in `style` becomes `new`: only the box that holds either one's ink is sent,
/// not the whole cell (the rest of the cell is the background in both). A digit of the pixel font is 5 x 7 of its
/// 6 x 10 cell: 58 % of the pixels. Nothing at or right of `right`.
pub fn redraw_char(c: &mut impl Canvas, style: &Style, (x, y, right): (u32, u32, u32), old: char, new: char) {
    let (fg, bg) = (c.ink(style.fg), c.ink(style.bg));
    let face = c.face();
    let ((_, a, ka), (font, g, k)) = (pick(style, face, old), pick(style, face, new));
    // each glyph's ink box in screen pixels from the cell's corner (the two may be drawn at different factors)
    let boxes = [(a, ka), (g, k)]
        .map(|(g, k)| (u32::from(g.x) * k, u32::from(g.y) * k, u32::from(g.x + g.w) * k, u32::from(g.y + g.h) * k));
    let inked = boxes.iter().filter(|b| b.2 > b.0 && b.3 > b.1);
    let (x0, y0, x1, y1) =
        inked.fold((u32::MAX, u32::MAX, 0, 0), |u, b| (u.0.min(b.0), u.1.min(b.1), u.2.max(b.2), u.3.max(b.3)));
    if x0 >= x1 {
        return; // neither has ink: nothing changes
    }
    let left = x + x0;
    let w = (x1 - x0).min(right.saturating_sub(left));
    if w == 0 {
        return;
    }
    let mut palette = [bg; 16];
    for (a, p) in palette.iter_mut().enumerate() {
        *p = blend(fg, bg, a as u8);
    }
    c.blit(left, y + y0, w, y1 - y0, &mut |px, py| {
        palette[usize::from(font.coverage(g, (px + x0) / k, (py + y0) / k))]
    });
}

/// Draws `s` in a box `w` wide from `x` (aligned inside it) and paints the rest of the box with the background, so a
/// shorter value leaves nothing of the previous one. Text wider than the box is cut at the box's last whole
/// character. Returns the width of the text drawn.
pub fn draw_in(c: &mut impl Canvas, style: &Style, x: u32, y: u32, w: u32, align: Align, s: &str) -> u32 {
    // Cut at the last whole character that fits. `get` and not `[..]`: slicing can panic, and its message alone
    // pulls about 8 KB of formatting and Unicode tables into the image.
    let mut s = s;
    while style.width(s) > w {
        let end = s.char_indices().next_back().map_or(0, |(i, _)| i);
        s = s.get(..end).unwrap_or("");
    }
    let tw = style.width(s);
    let left = match align {
        Align::Left => 0,
        Align::Centre => (w - tw) / 2,
        Align::Right => w - tw,
    };
    let h = style.height();
    c.fill(x, y, left, h, style.bg);
    draw(c, style, x + left, y, Align::Left, s);
    c.fill(x + left + tw, y, w - left - tw, h, style.bg);
    tw
}

/// A line of text built with `write!` into a fixed buffer (no heap): `N` bytes, the rest is dropped.
///
/// ```
/// use core::fmt::Write;
/// let mut l = bryton_rustfw::text::Line::<16>::new();
/// write!(l, "{:.1} km/h", 25.44).unwrap();
/// assert_eq!(l.as_str(), "25.4 km/h");
/// ```
#[derive(Clone, Copy, Debug)]
pub struct Line<const N: usize> {
    buf: [u8; N],
    len: usize,
}

/// Equal text (the bytes past it do not count).
impl<const N: usize> PartialEq for Line<N> {
    fn eq(&self, other: &Self) -> bool {
        self.as_str() == other.as_str()
    }
}

impl<const N: usize> Eq for Line<N> {}

impl<const N: usize> Default for Line<N> {
    fn default() -> Self {
        Self::new()
    }
}

impl<const N: usize> Line<N> {
    /// An empty line.
    pub const fn new() -> Self {
        Line { buf: [0; N], len: 0 }
    }

    /// The text so far.
    pub fn as_str(&self) -> &str {
        // Only whole characters are ever stored (write_str), so this never fails.
        core::str::from_utf8(&self.buf[..self.len]).unwrap_or("")
    }

    /// Empties it.
    pub fn clear(&mut self) {
        self.len = 0;
    }

    /// Appends `s`; what does not fit is dropped.
    pub fn push_str(&mut self, s: &str) {
        let _ = core::fmt::Write::write_str(self, s);
    }

    /// Appends `v` in decimal without core::fmt, whose number formatting costs several KB of image.
    ///
    /// ```
    /// let mut l = bryton_rustfw::text::Line::<16>::new();
    /// l.push_str("BLE ");
    /// l.push_u32(4);
    /// l.push_u32(4_294_967_295);
    /// assert_eq!(l.as_str(), "BLE 44294967295");
    /// ```
    pub fn push_u32(&mut self, v: u32) {
        let mut digits = [0u8; 10];
        let mut i = digits.len();
        let mut v = v;
        loop {
            i -= 1;
            digits[i] = b'0' + (v % 10) as u8;
            v /= 10;
            if v == 0 {
                break;
            }
        }
        self.push_str(core::str::from_utf8(&digits[i..]).unwrap_or(""));
    }
}

impl<const N: usize> core::fmt::Write for Line<N> {
    fn write_str(&mut self, s: &str) -> core::fmt::Result {
        for c in s.chars() {
            let mut tmp = [0; 4];
            let bytes = c.encode_utf8(&mut tmp).as_bytes();
            let Some(dst) = self.buf.get_mut(self.len..self.len + bytes.len()) else {
                return Ok(()); // full: the rest is dropped, which is fine for a screen line
            };
            dst.copy_from_slice(bytes);
            self.len += bytes.len();
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::fonts::PIXEL;
    use crate::ui::tests::Frame;
    use crate::ui::{BLACK, WHITE};

    const PIX2: Style = Style { font: &PIXEL, scale: 2, fg: WHITE, bg: BLACK };
    const PIX4: Style = Style { font: &PIXEL, scale: 4, fg: WHITE, bg: BLACK };

    #[test]
    fn every_glyph_fits_its_cell_and_its_data() {
        // the pixel font has the cue arrows too, on codes 1 to 10 (tools/pixel_font.py)
        assert_eq!(PIXEL.glyphs.len(), 0x7f - 0x20 + 10);
        for (i, g) in PIXEL.glyphs.iter().enumerate() {
            assert!(g.x + g.w <= g.advance && g.y + g.h <= PIXEL.height, "glyph {i} outside its cell");
            let bytes = (u32::from(g.w) * u32::from(g.h)).div_ceil(2);
            assert!((g.at + bytes) as usize <= PIXEL.alpha.len(), "glyph {i} past the data");
        }
    }

    /// Text lands where its width says, with ink inside and the background colour around it.
    #[test]
    fn draws_in_its_box() {
        let mut f = Frame::new();
        let w = draw(&mut f, &PIX2, 120, 10, Align::Centre, "USB");
        assert_eq!(w, PIX2.width("USB"));
        let x0 = 120 - w / 2;
        let ink = |x: u32, y: u32| f.at(x, y) != BLACK;
        let h = PIX2.height();
        assert!((x0..x0 + w).any(|x| (10..10 + h).any(|y| ink(x, y))));
        assert!((0..240).all(|x| !ink(x, 9) && !ink(x, 10 + h)), "ink outside the line");
        assert!((0..x0).chain(x0 + w..240).all(|x| (0..40).all(|y| !ink(x, y))), "ink outside the width");
        assert!((x0..x0 + w).any(|x| (10..10 + h).any(|y| f.at(x, y) == WHITE)), "no fully covered pixel");
    }

    /// Every character of every font into target/sim/fonts.bmp (pixel) and fonts_smooth.bmp (the FONT setting's
    /// smooth set at the same scales): a sheet to judge sizes and spacing on the host.
    #[test]
    fn font_sheet() {
        extern crate std;
        let ascii: std::string::String = (0x20u8..0x7f).map(char::from).collect();
        let arrows = "\x01\x02\x03\x04\x05\x06\x07\x08\x09\x0a"; // smooth: the pixel font's, same cells
        let px7 = Style { scale: 7, ..PIX2 };
        let dir = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("target/sim");
        std::fs::create_dir_all(&dir).unwrap();
        for (face, name) in [(Face::Pixel, "fonts.bmp"), (Face::Barlow, "fonts_barlow.bmp")] {
            let mut f = Frame::new();
            f.face = face;
            let mut y = 0;
            // All of ASCII at 2x; samples at 4x and 7x (all would not fit), and the cue arrows.
            for (style, sample) in [(&PIX2, ascii.as_str()), (&PIX4, "25.4km/h"), (&px7, "12:34"), (&PIX4, arrows)] {
                let mut line = std::string::String::new();
                for c in sample.chars() {
                    if style.width(&line) + u32::from(style.font.glyph(c).advance) * style.scale > 236 {
                        draw(&mut f, style, 2, y, Align::Left, &line);
                        y += style.height();
                        line.clear();
                    }
                    line.push(c);
                }
                draw(&mut f, style, 2, y, Align::Left, &line);
                y += style.height() + 4;
            }
            std::fs::write(dir.join(name), crate::sim::bmp(&f.px)).unwrap();
        }
    }

    /// The smooth set has the pixel font's cells: the same advance for every character (so every width in the UI
    /// holds), ink inside the cell, at most 5 cells of the scale wide (the blank column the layouts count on).
    #[test]
    fn smooth_fonts_share_the_pixel_cells() {
        for scale in 2..=8 {
            let face = Face::Barlow;
            let sf = crate::fonts::smooth(face, scale).unwrap();
            assert_eq!(u32::from(sf.height), 10 * scale);
            for (i, g) in sf.glyphs.iter().enumerate() {
                let p = &PIXEL.glyphs[i];
                assert!(g.advance == 0 || u32::from(g.advance) == u32::from(p.advance) * scale, "glyph {i} at {scale}");
                assert!(
                    u32::from(g.x + g.w) <= 5 * scale && u32::from(g.y + g.h) <= 10 * scale,
                    "glyph {i} at {scale}"
                );
            }
        }
        assert!(crate::fonts::smooth(Face::Barlow, 1).is_none() && crate::fonts::smooth(Face::Barlow, 9).is_none());
    }

    /// A shorter value in the same box leaves nothing of the longer one; the box is the only thing touched.
    #[test]
    fn draw_in_clears_the_rest_of_its_box() {
        for align in [Align::Left, Align::Centre, Align::Right] {
            let (mut a, mut b) = (Frame::new(), Frame::new());
            draw_in(&mut a, &PIX4, 20, 50, 200, align, "188.8");
            draw_in(&mut a, &PIX4, 20, 50, 200, align, "7");
            draw_in(&mut b, &PIX4, 20, 50, 200, align, "7");
            assert!(a.px == b.px, "{align:?}");
        }
        let mut f = Frame::new();
        assert_eq!(draw_in(&mut f, &PIX4, 0, 0, 30, Align::Left, "12345"), PIX4.width("1"), "cut to the box");
    }

    /// A scaled pixel font is the 1:1 drawing with every pixel a square.
    #[test]
    fn scaled_pixels_are_squares() {
        let (mut one, mut four) = (Frame::new(), Frame::new());
        let s1 = Style { scale: 1, ..PIX4 };
        draw(&mut one, &s1, 0, 0, Align::Left, "Ferris 42");
        let w = draw(&mut four, &PIX4, 0, 0, Align::Left, "Ferris 42");
        assert_eq!(w, 4 * s1.width("Ferris 42"));
        for y in 0..PIX4.height() {
            for x in 0..w {
                assert_eq!(four.at(x, y), one.at(x / 4, y / 4), "({x}, {y})");
            }
        }
        assert!((0..w).any(|x| four.at(x, 8) == WHITE));
    }

    #[test]
    fn line_drops_what_does_not_fit() {
        use core::fmt::Write;
        let mut l = Line::<4>::new();
        write!(l, "a\u{e9}cd").unwrap(); // the e acute takes 2 bytes
        assert_eq!(l.as_str(), "a\u{e9}c");
        l.clear();
        write!(l, "{}", 12).unwrap();
        assert_eq!(l.as_str(), "12");
    }

    #[test]
    fn unknown_characters_are_question_marks() {
        assert_eq!(PIX2.width("é"), PIX2.width("?"));
        let (mut a, mut b) = (Frame::new(), Frame::new());
        draw(&mut a, &PIX2, 0, 0, Align::Left, "\u{1f980}");
        draw(&mut b, &PIX2, 0, 0, Align::Left, "?");
        assert!(a.px == b.px);
    }

    #[test]
    fn right_aligned_text_ends_at_x() {
        let mut f = Frame::new();
        let w = draw(&mut f, &PIX4, 200, 100, Align::Right, "42");
        assert!((200..240).all(|x| (100..140).all(|y| f.at(x, y) == BLACK)));
        assert!((200 - w..200).any(|x| (100..140).any(|y| f.at(x, y) == WHITE)));
    }
}
